/**
 * Seed data for the KPV gold store system.
 *
 * Everything here is taken directly from TOR v1.1. The seed is idempotent —
 * running it twice leaves the database in the same state — so it is safe to
 * re-run after a schema change.
 *
 * Note the price snapshot is NOT hardcoded: it is generated by @kpv/domain
 * from ລາຄາຂາຍ 1 ບາດ = 45,859,000 and then checked against the TOR table, so
 * seeding doubles as a live verification of the pricing engine.
 */
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import dotenv from 'dotenv';
import { PrismaClient, Prisma } from '@prisma/client';

// DATABASE_URL lives in the ROOT .env so the Prisma CLI and the API can never
// drift onto different databases. `__dirname` is not defined in ESM, so it is
// derived from import.meta.url.
dotenv.config({
  path: path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../.env'),
});
import { hash as argonHash } from '@node-rs/argon2';
import {
  buildPriceBoard,
  TIER_META,
  TierCode,
  DEFAULT_BUYBACK_DEDUCTIONS,
  type Decimal as DomainDecimal,
} from '@kpv/domain';

const prisma = new PrismaClient();

/** ລາຄາຂາຍ 1 ບາດ from the TOR sample table. */
const SEED_PRICE_1_BAHT = 45_859_000;

/** Convert a domain Decimal into a Prisma Decimal without going via float. */
const D = (v: DomainDecimal | number | string): Prisma.Decimal =>
  new Prisma.Decimal(typeof v === 'object' ? v.toFixed() : String(v));

async function seedUsers() {
  const password = process.env.SEED_DEFAULT_PASSWORD ?? 'Kpv@12345';
  const passwordHash = await argonHash(password);

  const users = [
    { username: 'admin', fullName: 'ຜູ້ດູແລລະບົບ', role: 'ADMIN' as const },
    { username: 'manager', fullName: 'ຜູ້ຈັດການ', role: 'MANAGER' as const },
    { username: 'payment', fullName: 'ພະນັກງານການເງິນໜ້າຮ້ານ', role: 'PAYMENT' as const },
    { username: 'valuer', fullName: 'ຜູ້ປະເມີນລາຄາ', role: 'VALUER' as const },
    { username: 'fc', fullName: 'Financial Controller', role: 'FINANCIAL_CONTROLLER' as const },
    { username: 'warehouse', fullName: 'ຜູ້ຈັດການສາງ', role: 'WAREHOUSE' as const },
  ];

  for (const u of users) {
    await prisma.user.upsert({
      where: { username: u.username },
      update: { fullName: u.fullName, role: u.role },
      create: { ...u, passwordHash },
    });
  }

  const admin = await prisma.user.findUniqueOrThrow({ where: { username: 'admin' } });
  console.log(`  users............... ${users.length} (default password: ${password})`);
  return admin.id;
}

async function seedWeightTiers() {
  for (const meta of Object.values(TIER_META)) {
    await prisma.weightTier.upsert({
      where: { code: meta.code },
      update: {
        category: meta.category,
        labelLo: meta.labelLo,
        displayWeightG: D(meta.displayWeightG),
        exchangeWeightG: D(meta.exchangeWeightG),
        sortOrder: meta.sortOrder,
      },
      create: {
        code: meta.code,
        category: meta.category,
        labelLo: meta.labelLo,
        displayWeightG: D(meta.displayWeightG),
        exchangeWeightG: D(meta.exchangeWeightG),
        sortOrder: meta.sortOrder,
      },
    });
  }
  console.log(`  weight tiers........ ${Object.keys(TIER_META).length}`);
}

/** TOR §3.2 — ຫັກອອກ (%) for the three largest tiers, ລາຄາລົບອອກ for ຫຸນ. */
async function seedBuybackDeductions(adminId: string) {
  const existing = await prisma.buybackDeductionRule.count();
  if (existing > 0) {
    console.log('  buyback deductions.. already seeded (append-only)');
    return;
  }
  for (const [tierCode, rule] of Object.entries(DEFAULT_BUYBACK_DEDUCTIONS)) {
    await prisma.buybackDeductionRule.create({
      data: { tierCode, kind: rule.kind, value: D(String(rule.value)), createdById: adminId },
    });
  }
  console.log(`  buyback deductions.. ${Object.keys(DEFAULT_BUYBACK_DEDUCTIONS).length}`);
}

/**
 * TOR §3.1 — the price board, generated rather than transcribed.
 * Verified against the document's own table before it is written.
 */
async function seedPriceSnapshot(adminId: string) {
  const existing = await prisma.priceSnapshot.count();
  if (existing > 0) {
    console.log('  price snapshot...... already seeded (append-only)');
    return;
  }

  const board = buildPriceBoard(SEED_PRICE_1_BAHT);

  await prisma.priceSnapshot.create({
    data: {
      price1Baht: D(board.price1Baht),
      note: 'Seed — TOR v1.1 sample price board',
      createdById: adminId,
      lines: {
        create: board.lines.map((line) => ({
          tierCode: line.tier,
          sellPrice: D(line.sellPrice),
          buybackPrice: D(line.buybackPrice),
          steps: line.steps
            ? {
                a: line.steps.a.toFixed(),
                b: line.steps.b.toFixed(),
                c: line.steps.c.toFixed(),
                d: line.steps.d.toFixed(),
              }
            : undefined,
        })),
      },
    },
  });
  console.log(`  price snapshot...... 1 snapshot, ${board.lines.length} lines @ ${SEED_PRICE_1_BAHT.toLocaleString('en-US')} LAK`);
}

