/**
 * TOR §8.4 / §7.4 — default AP/AR (GOLD) posting rules.
 *
 * The TOR contradicts itself here: §8.1 describes gold sent out to
 * FACTORY / ຊ່າງນອກ as AR, while §8.4's rule list and §7.4's FACTORY
 * completion step both post it to AP. The shop settled this with the customer
 * and chose §8.4 + §7.4 — every movement lands on AP:
 *
 *   Stock IN  (EASY / FACTORY / ຊ່າງນອກ / ອື່ນໆ) -> +AP  (KPV owes gold)
 *   Stock OUT (FACTORY / ຊ່າງນອກ / ອື່ນໆ / WITHDRAW) -> -AP  (obligation cleared)
 *
 * §8.4's six bullets are three pairs, one per relationship — the shop
 * confirmed this reading:
 *
 *   1 ↔ 2   IN from ຊ່າງນອກ/ອື່ນໆ   ↔  OUT to ຊ່າງນອກ/ອື່ນໆ
 *   3 ↔ 4   IN from EASY             ↔  OUT to WITHDRAW
 *   5 ↔ 6   IN from FACTORY          ↔  OUT to FACTORY
 *
 * Pair 3↔4 is the one that needs care: the two halves name different
 * partners, yet they are the same obligation, so the WITHDRAW rule carries
 * `counterparty: 'EASY'` and both halves settle on EASY's row. Without it
 * EASY would climb forever while WITHDRAW ran negative.
 *
 * Consequence to know about: with every movement on AP, the AR (GOLD) module
 * has no posting rule and stays at zero — which matches §8.3, whose table is
 * itself labelled with AP columns.
 *
 * This table is Admin-editable, so reversing the decision is a data edit, not
 * a code change.
 */
async function seedGoldApArPostingRules() {
  const existing = await prisma.goldApArPostingRule.count();
  if (existing > 0) {
    console.log('  AP/AR gold rules.... already seeded');
    return;
  }
  const partners = await prisma.partnerSource.findMany({ where: { tracksGoldApAr: true } });
  const byCode = new Map(partners.map((p) => [p.code, p.id]));

  const rules: Array<{
    scope: 'NEW' | 'OLD';
    type: 'IN' | 'OUT';
    code: string;
    side: 'AP' | 'AR';
    sign: number;
    /** Book against this partner instead of `code` (see §8.4 pair 3↔4). */
    counterparty?: string;
    note: string;
  }> = [
    // Gold received into the shop -> +AP (KPV ຕິດໜີ້ຄຳຄູ່ຄ້າ).
    { scope: 'NEW', type: 'IN', code: 'EASY', side: 'AP', sign: 1, note: 'Stock IN ຈາກ EASY -> +AP (ຕິດໜີ້ຄຳ EASY)' },
    { scope: 'NEW', type: 'IN', code: 'FACTORY', side: 'AP', sign: 1, note: 'Stock IN ຈາກ FACTORY -> +AP (ຕິດໜີ້ຄຳ FACTORY)' },
    { scope: 'NEW', type: 'IN', code: 'OUTSOURCE_SMITH', side: 'AP', sign: 1, note: 'Stock IN ຈາກ ຊ່າງນອກ -> +AP (ຕິດໜີ້ຄຳ ຊ່າງນອກ)' },
    { scope: 'NEW', type: 'IN', code: 'OTHER', side: 'AP', sign: 1, note: 'Stock IN ຈາກ ອື່ນໆ -> +AP (ຕິດໜີ້ຄຳ ອື່ນໆ)' },
    // Gold sent out -> -AP (ລົບລ້າງພັນທະສົ່ງມອບຄຳ).
    { scope: 'OLD', type: 'OUT', code: 'FACTORY', side: 'AP', sign: -1, note: 'Stock OUT ໄປ FACTORY -> -AP (ລົບລ້າງພັນທະສົ່ງມອບຄຳ FACTORY)' },
    { scope: 'OLD', type: 'OUT', code: 'OUTSOURCE_SMITH', side: 'AP', sign: -1, note: 'Stock OUT ໄປ ຊ່າງນອກ -> -AP (ລົບລ້າງພັນທະສົ່ງມອບຄຳ ຊ່າງນອກ)' },
    { scope: 'OLD', type: 'OUT', code: 'OTHER', side: 'AP', sign: -1, note: 'Stock OUT ໄປ ອື່ນໆ -> -AP (ລົບລ້າງພັນທະສົ່ງມອບຄຳ ອື່ນໆ)' },
    // Handing gold back to EASY settles the payable.
    {
      scope: 'NEW',
      type: 'OUT',
      code: 'WITHDRAW',
      side: 'AP',
      sign: -1,
      // §8.4 pairs this with the EASY intake above, so it clears EASY's row.
      counterparty: 'EASY',
      note: 'Stock OUT WITHDRAW -> -AP (ລົບລ້າງພັນທະ EASY)',
    },
  ];

  let created = 0;
  for (const r of rules) {
    const partnerId = byCode.get(r.code);
    if (!partnerId) continue;
    await prisma.goldApArPostingRule.create({
      data: {
        scope: r.scope,
        type: r.type,
        partnerId,
        counterpartyId: r.counterparty ? (byCode.get(r.counterparty) ?? null) : null,
        side: r.side,
        sign: r.sign,
        note: r.note,
      },
    });
    created += 1;
  }
  console.log(`  AP/AR gold rules.... ${created}`);
}

/** TOR §3.7 — ໝວດລາຍຮັບ / ລາຍຈ່າຍ ຕັ້ງຕົ້ນ. */
