/** TOR §9.1 — ປະເພດລາຍການ AP-AR (Cash) ຕັ້ງຕົ້ນ. */
async function seedApArCashCategories() {
  const rows = [
    { code: 'LABOR_FEE', nameLo: 'ຄ່າແຮງຊ່າງ', side: 'AP' as const, sortOrder: 1 },
    { code: 'GOLD_PURCHASE', nameLo: 'ຄ່າຊື້ຄຳ', side: 'AP' as const, sortOrder: 2 },
    { code: 'CREDIT', nameLo: 'ສິນເຊື່ອລູກຄ້າ', side: 'AR' as const, sortOrder: 3 },
    { code: 'GOLD_SALE', nameLo: 'ຄ່າຂາຍຄຳຄ້າງຮັບ', side: 'AR' as const, sortOrder: 4 },
    { code: 'OTHER', nameLo: 'ອື່ນໆ', side: null, sortOrder: 5 },
  ];
  for (const row of rows) {
    await prisma.apArCashCategory.upsert({
      where: { code: row.code },
      update: row,
      create: row,
    });
  }
  console.log(`  ປະເພດ AP-AR (Cash). ${rows.length}`);
}

async function main() {
  console.log('\nSeeding KPV gold store database...\n');
  const adminId = await seedUsers();
  await seedWeightTiers();
  await seedBuybackDeductions(adminId);
  await seedPriceSnapshot(adminId);
  await seedExchangeRate(adminId);
  await seedJewelryConversionFees(adminId);
  await seedBarConversionFees(adminId);
  await seedSoftGoldFee(adminId);
  await seedGoldTypesAndItems();
  await seedPartnerSources();
  await seedBankAccounts();
  await seedCabinets();
  await seedGoldApArPostingRules();
  await seedIncomeExpenseCategories();
  await seedApArCashCategories();
  console.log('\nSeed complete.\n');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
